contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with inputs: amount to forward
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to forward");

        // Observe before-values
        address owner_before = c.owner(); if (__ESBMC_reverted()) return;
        uint bal_c_before = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after-values
        address owner_after = c.owner(); if (__ESBMC_reverted()) return;
        uint bal_c_after = address(c).balance;

        // General rule: either the call reverted, or owner remains same and c.balance did not increase
        assert(reverted || (owner_after == owner_before && bal_c_after <= bal_c_before));
    }

    receive() external payable { }
}

